    public void onCreate(Bundle b){super.onCreate(b);settings=new SecureSettings(this);settingsSection=getIntent().getStringExtra("setting")==null?"":getIntent().getStringExtra("setting");page=getIntent().getStringExtra("page")==null?"today":getIntent().getStringExtra("page");if(b!=null){page=b.getString("page","today");settingsSection=b.getString("settingsSection","");browseDay=b.getLong("browseDay",0);taskFilter=b.getString("taskFilter","all");timeFilter=b.getString("timeFilter","all");memoryFilter=b.getString("memoryFilter","accepted");}render();}
