            runOnUiThread(()->{if(isDestroyed()||root!=currentRoot)return;summary.removeAllViews();summary.addView(text("已到手机的录音",12,MUTED));summary.addView(title(DayOverview.duration(overview.recordedMs),28));summary.addView(text(overview.recordings+" 段录音  ·  "+overview.marks+" 个标记"+(overview.pending>0?"  ·  "+overview.pending+" 段待转写":""),12,SAGE));summary.addView(new DayOverview.Chart(this,overview),new LinearLayout.LayoutParams(-1,dp(80)));summary.addView(text("空白时段表示手机尚无录音；同步后会更新。",11,MUTED));});
