        TextView prev=text("‹",26,MUTED),next=text("›",26,MUTED);for(TextView arrow:new TextView[]{prev,next}){arrow.setGravity(Gravity.CENTER);month.addView(arrow,new LinearLayout.LayoutParams(dp(44),dp(48)));}final Calendar focused=(Calendar)anchor.clone();prev.setOnClickListener(v->{Calendar shifted=(Calendar)focused.clone();shifted.add(Calendar.WEEK_OF_YEAR,-1);browseDay=shifted.getTimeInMillis();render();});next.setOnClickListener(v->{Calendar shifted=(Calendar)focused.clone();shifted.add(Calendar.WEEK_OF_YEAR,1);browseDay=shifted.getTimeInMillis();render();});body.addView(month);
