        for(int i=0;i<7;i++){final long at=anchor.getTimeInMillis();boolean active=selected==at;LinearLayout col=column();col.setGravity(Gravity.CENTER);col.setPadding(0,dp(6),0,dp(6));col.setBackground(bg(active?ACCENT:TINT,16));TextView weekday=text(new java.text.SimpleDateFormat("E",AppLanguage.locale(this)).format(new Date(at)).replace("周","").replace("星期",""),11,active?Color.WHITE:MUTED);weekday.setGravity(Gravity.CENTER);col.addView(weekday);TextView dayNumber=text(new java.text.SimpleDateFormat("d",Locale.CHINA).format(new Date(at)),18,active?Color.WHITE:INK);dayNumber.setGravity(Gravity.CENTER);col.addView(dayNumber);TextView dot=text(store.rows("SELECT id FROM audio WHERE created>=? AND created<? LIMIT 1",String.valueOf(at),String.valueOf(nextDay(at))).length()>0?"•":" ",10,active?Color.WHITE:SAGE);dot.setPadding(0,0,0,0);dot.setGravity(Gravity.CENTER);col.addView(dot);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);if(i<6)lp.rightMargin=dp(5);week.addView(col,lp);col.setOnClickListener(v->{browseDay=at;render();});anchor.add(Calendar.DAY_OF_MONTH,1);}
