        readingMode=getSharedPreferences("understanding",0).getString("view","smart");LinearLayout modes=row();body.addView(modes);String[] modeIds={"full","smart","focus"},modeNames={"完整记录","智能精选","重点摘要"};for(int i=0;i<modeIds.length;i++){final String mode=modeIds[i];TextView chip=pill(modes,modeNames[i],readingMode.equals(mode)?Color.WHITE:MUTED,readingMode.equals(mode)?ACCENT:TINT);chip.setMinHeight(dp(44));chip.setGravity(Gravity.CENTER);chip.setOnClickListener(v->{getSharedPreferences("understanding",0).edit().putString("view",mode).apply();render();});}
        HorizontalScrollView horizontal=new HorizontalScrollView(this);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout filters=row();horizontal.addView(filters);body.addView(horizontal);String[] ids={"all","morning","afternoon","evening","marked"},names={"全部时段","清晨 00:00–12:00","午后 12:00–18:00","夜晚 18:00+","我的标记"};for(int i=0;i<ids.length;i++){final String id=ids[i];TextView chip=pill(filters,names[i],timeFilter.equals(id)?Color.WHITE:MUTED,timeFilter.equals(id)?ACCENT:TINT);chip.setMinHeight(dp(44));chip.setGravity(Gravity.CENTER);chip.setOnClickListener(v->{timeFilter=id;render();});}
