        LinearLayout actions=card(body);settingEntry(actions,"当天回顾","事件、总结与可核对的原声","sun",()->openReview(selected));settingEntry(actions,"长期记忆","待确认、已保存与已停用","heart",()->startActivity(new Intent(this,MainActivity.class).putExtra("memory_detail",true)));settingEntry(actions,"导出这一天","选择录音、转写、重点、总结与回顾","wave",()->startActivity(new Intent(this,ExportActivity.class).putExtra("day",selected)));
        button(body,"整理当天原文",()->timelineLoader.execute(()->{try(RecordStore db=new RecordStore(this)){JSONArray rows=db.rows(selection,selectionArgs);runOnUiThread(()->analyzeRecords(rows));}catch(Exception e){runOnUiThread(()->notice.setText("读取原文失败，请重试"));}}));

