    private void bumpPolicy(){android.content.SharedPreferences p=getSharedPreferences("capture-policy",0);p.edit().putLong("revision",p.getLong("revision",1)+1).commit();}
    private void provider(String role,String name,String explanation){if(role.equals("asr")){asrProvider();return;}LinearLayout c=card(body);c.addView(title(name,18));c.addView(text(explanation,12,MUTED));
        EditText url=field(c,"API 端点 (Base URL)",settings.endpoint(role),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);url.setSingleLine(true);url.setHint("https://provider.example/v1");EditText model=field(c,"模型名称",settings.model(role),InputType.TYPE_CLASS_TEXT);model.setSingleLine(true);EditText key=field(c,"API 密钥 (Token)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setSingleLine(true);key.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);key.setHint(settings.hasKey(role)?"已加密保存 · 留空保留":"输入 API Key（可留空）");
        if(role.equals("llm")){HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout presets=row();hs.addView(presets);c.addView(hs,1);String[] labels={"GPT-4o","Claude","DeepSeek","自建 Endpoint"};for(int n=0;n<labels.length;n++){final int choice=n;TextView preset=pill(presets,labels[n],ACCENT,TINT);preset.setMinHeight(dp(44));preset.setGravity(Gravity.CENTER);preset.setOnClickListener(v->{if(choice==0){url.setText("https://api.openai.com/v1");model.setText("gpt-4o");}else if(choice==1){url.setText("https://api.anthropic.com/v1");model.setText("claude-sonnet-4-5");}else if(choice==2){url.setText("https://api.deepseek.com/v1");model.setText("deepseek-chat");}else{url.setText("");model.setText("");}key.setText("");});}
            Switch strict=new Switch(this);strict.setText("服务支持严格 JSON Schema 时启用");strict.setTag("strict-json");strict.setChecked(getSharedPreferences("provider-json",0).getBoolean("strict",false));c.addView(strict);
            c.addView(text("思考调性与生成温度 (Temperature)",12,MUTED));float current=getSharedPreferences("provider-tone",0).getFloat("temperature",.7f);TextView tone=text(String.format(Locale.CHINA,"%.1f · %s",current,current<.4?"严谨提取":current<.9?"温暖陪伴":"诗意总结"),13,SAGE);c.addView(tone);SeekBar slider=new SeekBar(this);slider.setMax(12);slider.setProgress(Math.round(current*10));slider.setTag("temperature");slider.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));slider.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));c.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){tone.setText(String.format(Locale.CHINA,"%.1f · %s",value/10f,value<4?"严谨提取":value<9?"温暖陪伴":"诗意总结"));}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});
        }
        primary(c,"保存配置",()->{try{settings.saveProvider(role,url.getText().toString(),model.getText().toString(),key.getText().toString(),false);if(role.equals("llm")){getSharedPreferences("provider-json",0).edit().putBoolean("strict",((Switch)c.findViewWithTag("strict-json")).isChecked()).apply();SeekBar slider=(SeekBar)c.findViewWithTag("temperature");getSharedPreferences("provider-tone",0).edit().putFloat("temperature",slider.getProgress()/10f).apply();}key.setText("");notice.setText("已保存配置，密钥由 Android Keystore 加密保护");}catch(Exception e){notice.setText("配置无法保存，请检查地址与加密存储");}});
        button(c,"连通性测速",()->{try{String endpoint=ProviderAddress.validate(url.getText().toString());if(!endpoint.equals(settings.endpoint(role))||!model.getText().toString().equals(settings.model(role))||!key.getText().toString().isEmpty()){notice.setText("请先保存配置再测试");return;}new LocalDialog(this).setTitle("确认连通性检测").setMessage("访问你保存的服务，发送鉴权信息并读取服务响应，不发送录音或原文。原生 Claude 接口会发出一条极短的测试请求，可能产生少量费用。").setPositiveButton("开始检测",(d,w)->background(()->{long elapsed=new ProviderClient(this).ping(role);runOnUiThread(()->message("服务可访问","往返响应 "+elapsed+" ms"));},()->{})).setNegativeButton("取消",null).show();}catch(Exception e){notice.setText("请先保存有效的 API 地址");}});
        button(c,"清除这项密钥",()->{try{settings.saveProvider(role,settings.endpoint(role),settings.model(role),"",true);key.setText("");notice.setText("已清除");}catch(Exception e){notice.setText("清除失败");}});
    }
    private void asrProvider(){
        LinearLayout c=card(body);c.addView(title("云端语音转写 API",18));c.addView(text("整段上传录音；保存云端返回的时间、匿名说话人、逐词信息与警告。",12,MUTED));
        Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"标准 multipart · /audio/transcriptions","个人工作站 · 上传 + 异步任务"}));mode.setSelection(settings.asrMode().equals("workstation")?1:0);c.addView(mode);
        EditText url=field(c,"服务地址（含 /v1）",settings.endpoint("asr"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);url.setSingleLine(true);url.setHint("https://your-workstation.example/v1");c.addView(text("也可粘贴 /v1/audio/transcriptions 完整地址，保存时自动归一化。",11,MUTED));
        EditText model=field(c,"模型 / ASR 能力",settings.model("asr"),InputType.TYPE_CLASS_TEXT);model.setSingleLine(true);
        button(c,"选择工作站模型",()->new LocalDialog(this).setItems(new String[]{"Qwen3 ASR · asr.default · 30秒粗时间，无说话人","Whisper · asr.whisper · 字幕与逐词时间","MOSS · asr.moss · 会议匿名说话人","VibeVoice · asr.meeting · 会议匿名说话人"},(d,n)->{model.setText(new String[]{"asr.default","asr.whisper","asr.moss","asr.meeting"}[n]);mode.setSelection(1);EditText amount=(EditText)c.findViewWithTag("asr-budget");if(amount!=null)amount.setText(n==0?"1024":"16384");}).show());
        Spinner language=new Spinner(this);String[] languages={"auto","zh","en","ja","ko","yue"};language.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"自动检测语言","中文","English","日语","韩语","粤语"}));for(int i=0;i<languages.length;i++)if(languages[i].equals(settings.asrLanguage()))language.setSelection(i);c.addView(language);
        EditText prompt=field(c,"热词 / 会议背景（最多1000字）",settings.asrPrompt(),InputType.TYPE_CLASS_TEXT);EditText budget=field(c,"工作站输出预算",String.valueOf(settings.asrBudget()),InputType.TYPE_CLASS_NUMBER);budget.setTag("asr-budget");
        c.addView(text("Qwen 每块预算 128–2048；会议模型 512–32768（默认16384）。Whisper 使用 beam_size=5 和逐词时间。MOSS / VibeVoice 自动检测语言。标准接口请求 verbose_json。",11,MUTED));
        EditText key=field(c,"Bearer 设备密钥 / API Key","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setSingleLine(true);key.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);key.setHint(settings.hasKey("asr")?"已加密保存 · 留空保留":"需开通所选 asr 能力权限");
        primary(c,"保存转写配置",()->{try{String selected=model.getText().toString().trim();int amount=Integer.parseInt(budget.getText().toString());if(mode.getSelectedItemPosition()==1&&selected.matches("asr\\.(moss|meeting)")&&amount<512)throw new IllegalArgumentException("会议模型预算至少512");settings.saveAsr(url.getText().toString(),selected,key.getText().toString(),mode.getSelectedItemPosition()==1?"workstation":"standard",languages[language.getSelectedItemPosition()],prompt.getText().toString(),amount);url.setText(settings.endpoint("asr"));key.setText("");notice.setText("已保存；工作站密钥需有对应能力权限。实际转写前会确认发送范围。");}catch(Exception e){notice.setText("未保存："+e.getMessage());}});
        button(c,"清除转写密钥",()->{try{settings.saveProvider("asr",settings.endpoint("asr"),settings.model("asr"),"",true);key.setText("");notice.setText("已清除密钥");}catch(Exception e){notice.setText(e.getMessage());}});
        c.addView(text("会议模型匿名编号只在本次录音内有效，不代表真实姓名。工作站返回 truncated 时保留已有原文并提示重试。工作站原始上传不会随手机记录自动删除；取消任务会尝试 DELETE 服务端任务。",11,MUTED));
    }
    private void enableBluetoothReceiver(){
        if(Build.VERSION.SDK_INT>=31&&checkSelfPermission("android.permission.BLUETOOTH_CONNECT")!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.BLUETOOTH_CONNECT"},21);return;}
        android.bluetooth.BluetoothManager manager=(android.bluetooth.BluetoothManager)getSystemService(BLUETOOTH_SERVICE);
        android.bluetooth.BluetoothAdapter adapter=manager==null?null:manager.getAdapter();
        if(adapter==null){notice.setText("这台设备没有可用蓝牙");return;}
        if(!adapter.isEnabled()){startActivityForResult(new Intent(android.bluetooth.BluetoothAdapter.ACTION_REQUEST_ENABLE),22);return;}
        notifications();startForegroundService(new Intent(this,SyncService.class));new Handler().postDelayed(this::render,800);
    }
    public void onRequestPermissionsResult(int request,String[] permissions,int[] granted){super.onRequestPermissionsResult(request,permissions,granted);if(request==21){if(granted.length>0&&granted[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)enableBluetoothReceiver();else notice.setText("蓝牙同步需要附近设备权限；未开启接收");}}
    private void notifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},15);}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==22){if(result==RESULT_OK)enableBluetoothReceiver();else notice.setText("系统蓝牙未开启");return;}if(request==MEMO){if(result==RESULT_OK&&data!=null&&data.getStringExtra("id")!=null&&!data.getStringExtra("id").isEmpty())openRecord(data.getStringExtra("id"));return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;
        if(request==AVATAR)background(()->{android.graphics.Bitmap source;try(InputStream in=getContentResolver().openInputStream(data.getData())){if(in==null)throw new IOException("无法读取图片");android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inSampleSize=4;source=android.graphics.BitmapFactory.decodeStream(in,null,options);}if(source==null)throw new IOException("无法读取图片");int side=Math.min(source.getWidth(),source.getHeight());android.graphics.Bitmap crop=android.graphics.Bitmap.createBitmap(source,(source.getWidth()-side)/2,(source.getHeight()-side)/2,side,side);android.graphics.Bitmap scaled=android.graphics.Bitmap.createScaledBitmap(crop,128,128,true);try(OutputStream out=new FileOutputStream(new File(getFilesDir(),"profile-avatar.png"))){scaled.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}source.recycle();},this::render);
        if(request==IMPORT)background(()->{String id=store.importUri(data.getData());OfflineScheduler.enqueue(store,id);OfflineScheduler.schedule(this);if(settings.vadRequested()){store.addJob(id,"vad",new JSONObject());runOnUiThread(this::startJobs);}},this::render);
        if(request==EXPORT)background(()->{OutputStream out=getContentResolver().openOutputStream(data.getData());if(out==null)throw new IOException("无法写入目标文件");LocalExport.write(store,out);},()->notice.setText("已导出到你选择的位置，不含 API Key"));
    }
    protected void onResume(){super.onResume();if(settings!=null)render();transferVersion=TransferProgress.current.updated;refresh.removeCallbacks(syncRefresh);refresh.postDelayed(syncRefresh,1500);}
    protected void onPause(){refresh.removeCallbacks(syncRefresh);super.onPause();}
    void onUnderstandingUpdated(){if(page.equals("today")||page.equals("memory"))render();}
    public void onDestroy(){refresh.removeCallbacksAndMessages(null);timelineGeneration++;searchDelay.removeCallbacksAndMessages(null);timelineLoader.shutdownNow();super.onDestroy();}

